import { useEffect, useState } from "react";
import "../styles/Navbar.scss";

function Navbar() {
  const [menuOpen, setMenuOpen] = useState(false);
  const [active, setActive] = useState("home");

  const links = [
    ["home", "Home"],
    ["about", "About Me"],
    ["services", "Services"],
    ["skills", "Skills"],
    ["projects", "Projects"],
    ["contact", "Contact"],
  ];

  useEffect(() => {
    const handleScroll = () => {
      let current = "home";

      links.forEach(([id]) => {
        const section = document.getElementById(id);

        if (
          section &&
          window.scrollY >= section.offsetTop - 200
        ) {
          current = id;
        }
      });

      setActive(current);
    };

    window.addEventListener("scroll", handleScroll);

    handleScroll();

    return () => {
      window.removeEventListener("scroll", handleScroll);
    };
  }, []);

  const handleNavClick = (id) => {
    setActive(id);
    setMenuOpen(false);
  };

  return (
    <header className="header">

      {/* Logo */}

      <a
        href="#home"
        className="logo"
        onClick={() => handleNavClick("home")}
      >
        <span>M</span>
        <strong>Moses Raj</strong>
      </a>


      {/* Navigation */}

      <nav
        className={`navbar ${
          menuOpen ? "open" : ""
        }`}
      >

        {links.map(([id, name]) => (
          <a
            key={id}
            href={`#${id}`}
            className={
              active === id ? "active" : ""
            }
            onClick={() => handleNavClick(id)}
          >
            {name}
          </a>
        ))}

      </nav>


      {/* Mobile Menu */}

      <button
        type="button"
        className={`menu-btn ${
          menuOpen ? "open" : ""
        }`}
        onClick={() => setMenuOpen(!menuOpen)}
        aria-label={
          menuOpen
            ? "Close navigation"
            : "Open navigation"
        }
        aria-expanded={menuOpen}
      >
        <i
          className={`bx ${
            menuOpen
              ? "bx-x"
              : "bx-menu"
          }`}
        ></i>
      </button>

    </header>
  );
}

export default Navbar;
